import {tr,langs} from './i18n.js';
import {modules,canOpen} from './core/modules.js';
import {workspacePage,toggleSample,toggleCoachLanguage,resetWorkspace} from './core/workspace.js';
import {identityPage,workspaceRole} from './core/identity-ui.js';
const $=s=>document.querySelector(s);
let lang=localStorage.getItem('ml-language')||'ar', state=null, page='home', feed='forYou', liveTab='match', query='', roleFilter='all', onlineOnly=false, chatId=null, authMode='login', modalPayload=null, busy=false, config={production:false,demo:false}, authEmail='';
if(!langs.includes(lang))lang='ar';
const t=k=>tr(config.production?({local:'publicPilot',localNote:'publicNote',adminNotice:'publicAdminNotice'}[k]||k):k,lang);
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'<path d="m3 10 9-7 9 7v10H15v-6H9v6H3z"/>',social:'<circle cx="9" cy="8" r="3"/><path d="M2 21v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v2"/>',live:'<circle cx="12" cy="12" r="2"/><path d="M7 7a7 7 0 0 0 0 10m10-10a7 7 0 0 1 0 10M4 4a11 11 0 0 0 0 16M20 4a11 11 0 0 1 0 16"/>',chat:'<path d="M21 11.5a9 9 0 0 1-9 9L3 22l1.5-5A9 9 0 1 1 21 11.5Z"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',explore:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',notifications:'<path d="M18 8a6 6 0 0 0-12 0c0 8-3 8-3 9h18c0-1-3-1-3-9M10 21h4"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m10 2-1 3-3 1-3-1-2 4 2 3-1 3 2 4 4-1 2 3h4l1-3 3-1 3 1 2-4-2-3 1-3-2-4-4 1-2-3Z"/>',plus:'<path d="M12 4v16M4 12h16"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',send:'<path d="m22 2-7 20-4-9L2 9l20-7ZM22 2 11 13"/>',trophy:'<path d="M8 3h8v8a4 4 0 0 1-8 0zm0 3H3v2a4 4 0 0 0 5 4m8-6h5v2a4 4 0 0 1-5 4M12 15v5m-6 1h12"/>',dumbbell:'<path d="M4 8v8m4-11v14m8-14v14m4-11v8M8 12h8"/>',zap:'<path d="m13 2-8 12h7l-1 8 8-12h-7z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',shield:'<path d="m12 2 9 4v6c0 5-5 9-9 10-4-1-9-5-9-10V6z"/><path d="m8 12 3 3 5-6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',flag:'<path d="M5 22V3h14l-2 5 2 5H5"/>',logout:'<path d="M10 3H4v18h6m5-15 6 6-6 6m-6-6h12"/>',share:'<circle cx="18" cy="5" r="3"/><circle cx="5" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8 10 7-4m-7 8 7 4"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="2"/><path d="m3 18 6-6 5 5 3-3 4 4"/>'};
const ic=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.profile}</svg>`;
const btn=(label,action,attrs='',kind='secondary',icon='')=>`<button class="${kind}" data-action="${action}" ${attrs}>${icon?ic(icon):''}${h(label)}</button>`;
const navs=['home','social','live','chat','profile'];
const brand=()=>`<div class="brand"><img src="/logo.svg" alt=""><div><span>MUSCLIVO <b>LIVE</b></span><div class="tagline">NEVER TRAIN ALONE</div></div></div>`;
const avatar=(p,cls='')=>`<div class="avatar ${h(p?.role||'')} ${cls}">${h(p?.name?.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()||'?')}</div>`;
const get=id=>id===state?.me.id?state.me:state?.profiles.find(p=>p.id===id)||{id,name:t('notAvailable'),role:'athlete',status:'offline'};
const displayDate=at=>new Date(at).toLocaleString(lang==='ar'?'ar':lang==='sv'?'sv-SE':'en-GB',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const badge=(label,color='green')=>`<span class="badge ${color}">${h(label)}</span>`;
const status=p=>`<span class="${p.status==='ready'?'green':p.status==='training'?'gold':'muted'}"><span class="dot"></span> ${t(p.status==='ready'?'online':p.status==='training'?'training':'offline')}</span>`;
const empty=()=>`<div class="empty">${t('noItems')}</div>`;
const heading=(key,action='',label='seeAll')=>`<div class="section-head"><h2>${t(key)}</h2>${action?btn(t(label),action,'','chip'):''}</div>`;
const art=()=>`<svg class="hero-art" viewBox="0 0 300 280" fill="none" aria-hidden="true"><g opacity=".26" stroke="#39FF88"><circle cx="190" cy="135" r="106"/><circle cx="190" cy="135" r="82"/><circle cx="190" cy="135" r="55"/><path d="M25 135h280M190 0v280"/></g><g transform="translate(166 132) rotate(-28)"><rect x="-104" y="-7" width="208" height="14" rx="7" fill="#A1C9AE"/><rect x="-102" y="-38" width="20" height="76" rx="5" fill="#39FF88"/><rect x="-80" y="-54" width="26" height="108" rx="6" fill="#216740"/><rect x="-55" y="-45" width="19" height="90" rx="4" fill="#39FF88"/><rect x="36" y="-45" width="19" height="90" rx="4" fill="#39FF88"/><rect x="55" y="-54" width="26" height="108" rx="6" fill="#216740"/><rect x="82" y="-38" width="20" height="76" rx="5" fill="#39FF88"/></g><path d="m229 27-40 47h25l-10 36 49-53h-29z" fill="#39FF88" opacity=".4"/></svg>`;
function person(p,actions='',extra=''){return `<div class="person-row">${avatar(p)}<div class="grow"><div class="row wrap"><b>${h(p.name)}</b>${p.verified?badge('✓ '+t('verified')):''}</div><small>${h(t(p.role))} · ${h(p.city||'—')} · ${h(p.sport||'—')}</small><div><small>${status(p)}</small></div>${extra}</div>${actions}</div>`}
function api(path,body){return fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined}).then(async r=>{const j=await r.json();if(!r.ok)throw Object.assign(new Error(j.error),{status:r.status});return j})}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3500)}
function applyTheme(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.documentElement.dataset.theme=state?.me.theme||localStorage.getItem('ml-theme')||'dark'}
const langSelect=()=>`<select class="lang" id="lang-select" aria-label="${t('language')}">${langs.map(x=>`<option value="${x}" ${lang===x?'selected':''}>${x.toUpperCase()}</option>`).join('')}</select>`;
function auth(){
  const registration=authMode==='register', verify=authMode==='verify', reset=authMode==='reset', forgot=authMode==='forgot', authenticated=authMode==='login';
  const label=registration?'register':verify?'verifyEmail':reset?'reset':forgot?'forgot':'login';
  const policyLinks=()=>`<div class="row wrap"><a href="/privacy?lang=${lang}" target="_blank" rel="noopener">${t('privacyPolicy')}</a><a href="/terms?lang=${lang}" target="_blank" rel="noopener">${t('terms')}</a></div>`;
  $('#app').innerHTML=`<main class="auth"><div class="auth-brand">${brand()}${art()}<h1>NEVER TRAIN ALONE.</h1><p>TRAIN. CONNECT. EVOLVE.</p></div><div class="stack"><div class="row space">${badge(t('local'),'gold')}${langSelect()}</div><div class="card auth-form"><h1>${t(label)}</h1><p class="muted">${t('localNote')}</p><form class="stack" data-form="auth">${registration?`<label>${t('name')}<input name="name" required maxlength="60" autocomplete="name"></label><label>${t('role')}<select name="role">${['athlete','coach','gym'].map(r=>`<option value="${r}">${t(r)}</option>`).join('')}</select></label>`:''}<label>${t('email')}<input name="email" type="email" value="${h(authEmail)}" required autocomplete="email"></label>${verify||reset?`<label>${t('verificationCode')}<input name="code" required maxlength="48" autocomplete="one-time-code"></label>`:''}${authenticated||registration||reset?`<label>${t('password')}<input name="password" type="password" required minlength="${config.production?12:8}" maxlength="128" autocomplete="${authenticated?'current-password':'new-password'}"></label>`:''}${registration&&config.production?`<label class="check-row"><input type="checkbox" name="acceptPolicies" required>${t('agree')}</label><label class="check-row"><input type="checkbox" name="adult" required>${t('adult')}</label>${policyLinks()}`:''}<button class="primary" type="submit">${t(label)}</button></form>${authenticated?btn(t('register'),'authMode','data-id="register"','secondary'):btn(t('login'),'authMode','data-id="login"','secondary')}${config.production&&authenticated?`<div class="row wrap">${btn(t('forgot'),'authMode','data-id="forgot"','chip')}${btn(t('verifyEmail'),'authMode','data-id="verify"','chip')}</div>`:''}${config.production&&verify?btn(t('resend'),'resend','','chip'):''}</div>${config.demo?`<div class="card stack"><h3>${t('demo')}</h3><small>${t('demoInfo')}</small><div class="grid">${['athlete','coach','gym','admin'].map(r=>btn(t(r),'demo',`data-id="${r}"`,'secondary')).join('')}</div></div>`:''}${policyLinks()}</div></main>`;
}
function nav(key){return `<button class="nav-link ${page===key?'active':''}" data-action="nav" data-id="${key}" aria-current="${page===key?'page':'false'}">${ic(key==='admin'?'shield':key==='challenges'?'trophy':key)}<span>${t(key)}</span></button>`}
function render(){
  applyTheme();if(!state){auth();return}
  if(page==='admin'&&state.me.role!=='admin')page='home';
  if((page==='workspace'&&config.production)||(page==='identity'&&(!state.identity||config.production))||(modules.some(m=>m.id===page)&&!canOpen(page,workspaceRole(state),config.production)))page='home';
  const unread=state.notifications.filter(x=>!x.read).length;
  const corePage=page==='workspace'||modules.some(m=>m.id===page);
  const content=page==='identity'?()=>identityPage({state,t,h,btn}):corePage?()=>workspacePage({state,id:page,production:config.production,t,h,ic,btn,person,lang}):({home,social,live,chat,profile:profilePage,explore,notifications,settings,challenges,admin})[page]||home;
  $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar">${brand()}<nav class="nav-list">${navs.map(nav).join('')}${!config.production?nav('workspace'):''}${state.identity&&!config.production?nav('identity'):''}${nav('explore')}${nav('challenges')}${nav('notifications')}${state.me.role==='admin'?nav('admin'):''}</nav><div class="sidebar-footer stack"><div class="row">${avatar(state.me)}<div class="profile-text"><b>${h(state.me.name)}</b><br><small>${t(state.me.role)}</small></div></div>${nav('settings')}${btn(t('logout'),'logout','','secondary','logout')}<div class="notice">${t('local')}</div></div></aside><main class="main"><header class="topbar">${brand()}<span class="title">${t(page)}</span><div class="actions">${langSelect()}${!config.production?btn('', 'nav',`data-id="workspace" aria-label="${t('workspace')}" title="${t('workspace')}"`,'icon-button','dumbbell'):''}<button class="icon-button" data-action="nav" data-id="explore" aria-label="${t('explore')}">${ic('explore')}</button><button class="icon-button" data-action="nav" data-id="notifications" aria-label="${t('notifications')}">${ic('notifications')}${unread?`<span class="green">${unread}</span>`:''}</button><button class="icon-button mobile-only" data-action="nav" data-id="settings" aria-label="${t('settings')}">${ic('settings')}</button></div></header><div class="main-content">${content()}</div></main><nav class="bottom-nav">${navs.map(nav).join('')}</nav></div>`;
  if(['home','workspace','profile'].includes(page)&&state.identity&&!config.production)$('.main-content').insertAdjacentHTML('afterbegin',`<section class="card row wrap workspace-entry"><div class="grow"><h3>${t('identity')}</h3><small>${t('identity_'+state.identity.active.role)} · ${h(state.identity.club?.name||t('identityPersonal'))}</small></div>${btn(t('identitySwitchLabel'),'nav','data-id="identity"','secondary','shield')}</section>`);
  if(page==='home'&&!config.production)$('.main-content').insertAdjacentHTML('afterbegin',`<section class="card row wrap workspace-entry"><div class="grow"><h3>${t('workspace')}</h3><small>${t('workspaceIntro')}</small></div>${btn(t('seeAll'),'nav','data-id="workspace"','primary','dumbbell')}</section>`);
  if(page==='settings')$('.main-content').insertAdjacentHTML('beforeend',`<section class="card stack account-panel"><h2>${t('privacy')}</h2>${btn(t('dataExport'),'account','data-id="dataExport"','secondary')}${btn(t('logoutAll'),'account','data-id="logoutAll"','secondary')}${state.me.role!=='admin'?btn(t('deleteAccount'),'account','data-id="deleteAccount"','danger'):''}<div class="row wrap"><a href="/privacy?lang=${lang}">${t('privacyPolicy')}</a><a href="/terms?lang=${lang}">${t('terms')}</a></div></section>`);
  document.querySelectorAll('[data-action=follow]').forEach(el=>{if((state.followRequests||[]).some(r=>r.from===state.me.id&&r.to===el.dataset.id))el.textContent=t('cancelRequest')});
  const m=$('.messages');if(m)m.scrollTop=m.scrollHeight;
}
function home(){
  const available=state.profiles.filter(p=>p.status==='ready'&&p.matchable&&p.id!==state.me.id);
  return `<div class="stack"><div class="row space"><div><p class="eyebrow">MUSCLIVO LIVE / COMMUNITY</p><h2>${t('welcome')}, ${h(state.me.name.split(' ')[0])} 👋</h2></div>${badge(t('local'),'gold')}</div><div class="hero">${art()}<span class="eyebrow">● ${available.length} ${t('online')}</span><h1>${t('readyTitle')}</h1><p>${t('heroText')}</p>${btn(t('trainNow'),'nav','data-id="live"','primary','zap')}</div><div class="columns"><div class="stack"><div class="grid">${[['partner','dumbbell','live','match'],['coach','shield','live','coach'],['groups','social','live','sessions'],['challenges','trophy','challenges','']].map(([label,icon,target,tab])=>`<button class="card quick" data-action="jump" data-id="${target}" data-tab="${tab}">${ic(icon)}<b>${t(label)}</b><small>${t('seeAll')} →</small></button>`).join('')}</div><div class="card">${heading('sessions','sessionsNav')}${state.sessions.filter(s=>s.at>Date.now()).slice(0,3).map(sessionCard).join('')||empty()}</div></div><aside class="stack"><div class="card stack"><div class="row space"><h3>${t('status')}</h3>${status(state.me)}</div><select id="presence" aria-label="${t('status')}">${[['ready','online'],['training','training'],['offline','offline']].map(([v,k])=>`<option value="${v}" ${state.me.status===v?'selected':''}>${t(k)}</option>`).join('')}</select></div><div class="card stack">${heading('available','liveNav')}${available.slice(0,4).map(p=>person(p,btn(t('sendRequest'),'request',`data-id="${p.id}"`,'chip'))).join('')||empty()}</div><div class="card stack"><h3>${t('freeGoal')}</h3><div class="stat green">€0</div><small>${t('localNote')}</small></div></aside></div></div>`;
}
function postCard(p){const author=get(p.owner), liked=p.likes.includes(state.me.id), saved=state.saved.some(x=>x.post===p.id);
  return `<article class="card"><div class="row">${avatar(author)}<div class="grow"><b>${h(author.name)}</b> ${author.verified?badge('✓'):''}<br><small>${h(t(p.type==='text'?'textPost':p.type))} · ${displayDate(p.at)}</small></div>${p.owner===state.me.id||state.me.role==='admin'?btn('','deletePost',`data-id="${p.id}" aria-label="${t('remove')}"`,'icon-button','close'):btn('','reportPost',`data-id="${p.id}" aria-label="${t('report')}"`,'icon-button','flag')}</div><p class="post-text">${h(p.text)}</p>${p.image?`<img class="post-image" src="${h(p.image)}" alt="${t('image')}">`:''}<div class="post-actions"><button data-action="like" data-id="${p.id}" class="${liked?'selected':''}" aria-label="${t('like')}">${ic('heart')} ${p.likes.length}</button><button data-action="comments" data-id="${p.id}">${ic('chat')} ${p.comments.length}</button><button data-action="share" data-id="${p.id}">${ic('share')} ${t('share')}</button><span class="grow"></span><button data-action="save" data-id="${p.id}" class="${saved?'selected':''}" aria-label="${t('save')}">${ic('bookmark')}</button></div></article>`}
function social(){let posts=state.posts;if(feed==='following')posts=posts.filter(p=>state.follows.some(f=>f.from===state.me.id&&f.to===p.owner));if(feed==='saved')posts=posts.filter(p=>state.saved.some(x=>x.post===p.id));
  return `<div class="columns"><div class="stack"><div class="card stack"><h3>${t('stories')}</h3><div class="story-list"><button class="story-item" data-action="newStory"><div class="avatar story story-plus">${ic('plus')}</div><span>${t('yourStory')}</span></button>${state.stories.map(s=>`<button class="story-item" data-action="viewStory" data-id="${s.id}">${avatar(get(s.owner),'story')}<span>${h(get(s.owner).name)}</span></button>`).join('')}</div></div><div class="card stack"><div class="row">${avatar(state.me)}<button class="secondary grow button-text" data-action="newPost">${t('shareThought')}</button><button class="icon-button" data-action="newPost" aria-label="${t('post')}">${ic('image')}</button></div></div><div class="tabs">${['forYou','following','saved'].map(x=>btn(t(x),'feed',`data-id="${x}"`,'chip '+(feed===x?'active':''))).join('')}</div><div class="feed">${posts.map(postCard).join('')||empty()}</div></div><aside class="card stack"><h3>${t('explore')}</h3>${state.profiles.filter(p=>p.id!==state.me.id).map(p=>person(p,btn(t(state.follows.some(f=>f.from===state.me.id&&f.to===p.id)?'unfollow':'follow'),'follow',`data-id="${p.id}"`,'chip'))).join('')||empty()}</aside></div>`
}
function score(p){const m=state.me;return 25*(p.sport===m.sport)+25*(p.status==='ready')+20*(!!p.city&&p.city===m.city)+15*(p.goal===m.goal)+10*(p.level===m.level)+5*(p.lang===m.lang)}
function sessionCard(s){const joined=s.participants.includes(state.me.id);return `<div class="rule row"><div class="avatar gym">${ic('calendar')}</div><div class="grow"><b>${h(s.title)}</b><br><small>${h(get(s.owner).name)} · ${displayDate(s.at)} · ${s.participants.length} ${t('members')}</small></div>${s.at>Date.now()?btn(t(joined?'leave':'join'),'joinSession',`data-id="${s.id}"`,joined?'secondary':'chip active'):''}</div>`}
function live(){
  let candidates=state.profiles.filter(p=>p.id!==state.me.id&&p.status==='ready'&&p.matchable);if(liveTab==='coach')candidates=candidates.filter(p=>p.role==='coach');else candidates=candidates.filter(p=>p.role==='athlete');
  const pending=state.requests.filter(r=>r.to===state.me.id&&r.state==='pending');
  return `<div class="stack"><div class="hero">${art()}<span class="eyebrow">MUSCLIVO MATCH</span><h1>${t('readyTitle')}</h1><p>${t('heroText')}</p><div class="row wrap">${btn(t('online'),'setReady','','primary','zap')} ${status(state.me)}</div></div><div class="tabs">${[['match','match'],['coach','coach'],['sessions','groups'],['requests','requests']].map(([v,k])=>btn(t(k)+(v==='requests'&&pending.length?' ('+pending.length+')':''),'liveTab',`data-id="${v}"`,'chip '+(liveTab===v?'active':''))).join('')}</div>${liveTab==='sessions'?`<div class="card stack"><div class="row space"><h2>${t('sessions')}</h2>${(['coach','gym'].includes(state.me.role)&&state.me.verified)?btn(t('newSession'),'newSession','','primary','plus'):''}</div>${state.sessions.map(sessionCard).join('')||empty()}</div>`:liveTab==='requests'?`<div class="card stack"><h2>${t('requests')}</h2>${state.requests.map(r=>`<div class="rule row wrap">${avatar(get(r.from===state.me.id?r.to:r.from))}<div class="grow"><b>${h(get(r.from===state.me.id?r.to:r.from).name)}</b><br><small>${h(r.sport)} · ${t(r.state)} · ${displayDate(r.at)}</small></div>${r.to===state.me.id&&r.state==='pending'?btn(t('accept'),'respond',`data-id="${r.id}" data-accept="true"`,'primary')+btn(t('decline'),'respond',`data-id="${r.id}" data-accept="false"`):''}</div>`).join('')||empty()}</div>`:`<h2>${t('matchResult')}</h2><div class="grid">${candidates.sort((a,b)=>score(b)-score(a)).map(p=>`<article class="card stack"><div class="row space">${avatar(p,'large')}<div class="match-score">${score(p)}%<small> ${t('matchScore')}</small></div></div><div><h2>${h(p.name)} ${p.verified?badge('✓'):''}</h2><small>${status(p)}</small></div><div class="rule stack"><small>${ic('pin')} ${h(p.city||'—')}</small><small>${ic('dumbbell')} ${h(p.sport)}</small><small>${t('goal')}: ${h(p.goal)}</small><small>${t('level')}: ${h(p.level)}</small></div>${btn(t('sendRequest'),'request',`data-id="${p.id}"`,'primary')}</article>`).join('')||empty()}</div>`}</div>`
}
function chatName(c){return c.name||c.members.filter(id=>id!==state.me.id).map(id=>get(id).name).join(', ')}
function chat(){const list=state.conversations;const c=list.find(x=>x.id===chatId)||list[0];if(c)chatId=c.id;
return `<div class="stack"><div class="row space"><h2>${t('chat')}</h2>${btn(t('newChat'),'newChat','','primary','plus')}</div><div class="chat-layout"><div class="card chat-list">${list.map(x=>`<button class="${c?.id===x.id?'active':''}" data-action="openChat" data-id="${x.id}"><div class="row">${avatar(get(x.members.find(id=>id!==state.me.id)))}<div class="grow"><b>${h(chatName(x))}</b><br><small>${h(x.messages.at(-1)?.text?.slice(0,40)||'—')}</small></div></div></button>`).join('')||empty()}</div><div class="card stack">${c?`<div class="row space"><div class="row">${avatar(get(c.members.find(id=>id!==state.me.id)))}<b>${h(chatName(c))}</b></div>${btn(t('invite'),'invite',`data-id="${c.id}"`,'chip','calendar')}</div><div class="messages rule">${c.messages.map(m=>`<div class="bubble ${m.owner===state.me.id?'mine':''}">${c.members.length>2?`<small>${h(get(m.owner).name)}</small><br>`:''}${h(m.text)}<br><small>${displayDate(m.at)}</small></div>`).join('')||empty()}</div><form class="chat-form" data-form="message" data-id="${c.id}"><input name="text" placeholder="${t('message')}" required maxlength="1000" autocomplete="off"><button class="primary" type="submit" aria-label="${t('send')}">${ic('send')}</button></form>`:`<div class="empty">${t('noChat')}</div>`}</div></div></div>`}
const stat=(n,key)=>`<div class="stat-box"><div class="stat">${n}</div><small>${t(key)}</small></div>`;
function profilePage(){const p=state.me;return `<div class="columns"><div class="stack"><div class="card stack"><div class="profile-cover"></div><div class="profile-top row">${avatar(p,'large')}<div class="grow"><h2>${h(p.name)} ${p.verified?badge('✓'):''}</h2><small>${t(p.role)} · ${h(p.city||'—')}</small></div>${btn(t('edit'),'editProfile','','primary')}</div><p>${h(p.bio||'—')}</p><div class="stats">${stat(state.posts.filter(x=>x.owner===p.id).length,'posts')}${stat(state.follows.filter(x=>x.to===p.id).length,'followers')}${stat(state.follows.filter(x=>x.from===p.id).length,'following')}</div><div class="row wrap">${badge(p.sport||'—')}${badge(p.level||'—')}${badge(p.goal||'—')}</div></div><h2>${t('posts')}</h2>${state.posts.filter(x=>x.owner===p.id).map(postCard).join('')||empty()}</div><aside class="stack"><div class="card stack"><h3>${ic('trophy')} ${t('achievements')}</h3><div class="stat green">${p.xp} XP</div>${btn(t('challenges'),'nav','data-id="challenges"','secondary')}</div>${['coach','gym'].includes(p.role)&&!p.verified?`<div class="card stack"><h3>${t('verification')}</h3>${state.verifications[0]?badge(state.verifications[0].state):''}${btn(t('verification'),'verification','','secondary')}</div>`:''}<div class="card stack">${btn(t('settings'),'nav','data-id="settings"','secondary','settings')}${state.me.role==='admin'?btn(t('admin'),'nav','data-id="admin"','primary','shield'):''}${btn(t('logout'),'logout','','secondary','logout')}</div></aside></div>`}
function explore(){const p=state.profiles.filter(p=>p.id!==state.me.id&&(roleFilter==='all'||p.role===roleFilter)&&(!onlineOnly||p.status==='ready')&&[p.name,p.city,p.sport,p.goal].some(v=>String(v).toLowerCase().includes(query.toLowerCase())));
return `<div class="stack"><h1>${t('explore')}</h1><form class="row" data-form="search"><input type="search" name="query" placeholder="${t('search')}" value="${h(query)}"><button class="primary">${ic('explore')}</button></form><div class="row wrap">${['all','athlete','coach','gym'].map(r=>btn(t(r),'filter',`data-id="${r}"`,'chip '+(roleFilter===r?'active':''))).join('')} ${btn(t('onlineOnly'),'onlineFilter','','chip '+(onlineOnly?'active':''))}</div><div class="grid">${p.map(x=>`<div class="card stack">${person(x)}<p>${h(x.bio)}</p><div class="row wrap">${btn(t(state.follows.some(f=>f.from===state.me.id&&f.to===x.id)?'unfollow':'follow'),'follow',`data-id="${x.id}"`,'primary')}${btn(t('chat'),'directChat',`data-id="${x.id}"`,'secondary')}${btn(t('block'),'block',`data-id="${x.id}"`,'chip')}${btn(t('report'),'reportProfile',`data-id="${x.id}"`,'chip')}</div></div>`).join('')||empty()}</div></div>`}
function notifications(){const keys={like:'liked',comment:'commented',follow:'followed',request:'newRequest',message:'newMessage',accepted:'accepted',declined:'declined',followRequest:'followRequest'};return `<div class="stack"><div class="row space"><h1>${t('notifications')}</h1>${btn(t('markRead'),'readNotifications')}</div>${(state.followRequests||[]).filter(r=>r.to===state.me.id).map(r=>`<div class="card row wrap">${avatar(get(r.from))}<div class="grow"><b>${h(get(r.from).name)}</b><br><small>${t('followRequest')}</small></div>${btn(t('accept'),'respondFollow',`data-id="${r.id}" data-accept="true"`,'primary')}${btn(t('decline'),'respondFollow',`data-id="${r.id}" data-accept="false"`,'secondary')}</div>`).join('')}${state.notifications.map(n=>`<div class="card row">${avatar(get(n.actor))}<div class="grow"><b>${h(get(n.actor).name)} ${t(keys[n.text]||n.text)}</b><br><small>${displayDate(n.at)}</small></div>${!n.read?'<span class="dot green"></span>':''}</div>`).join('')||empty()}</div>`}
const opt=(values,value)=>values.map(x=>`<option value="${x}" ${x===value?'selected':''}>${t(x==='followers'?'followers':x)}</option>`).join('');
function settings(){const p=state.me.privacy;return `<div class="stack"><h1>${t('settings')}</h1><div class="card stack"><h2>${t('privacy')}</h2><form class="stack" data-form="settings">${[['profile','profileVisibility'],['posts','postVisibility'],['messages','messageVisibility'],['stories','storyVisibility']].map(([k,label])=>`<label>${t(label)}<select name="${k}">${opt(['everyone','followers','private'],p[k])}</select></label>`).join('')}${[['presence','showPresence'],['match','allowMatch'],['notifications','allowNotifications']].map(([k,label])=>`<label class="check-row"><input type="checkbox" name="${k}" ${p[k]?'checked':''}>${t(label)}</label>`).join('')}<div class="form-row"><label>${t('language')}<select name="lang">${opt(langs,lang)}</select></label><label>${t('theme')}<select name="theme">${opt(['dark','light'],state.me.theme||'dark')}</select></label></div><button class="primary" type="submit">${t('save')}</button></form></div><div class="card stack"><h2>${t('blocked')}</h2>${state.blocks.map(b=>`<div class="row space"><span>${h(b.to)}</span>${btn(t('unblock'),'block',`data-id="${b.to}"`)}</div>`).join('')||empty()}</div>${state.me.role==='admin'?btn(t('admin'),'nav','data-id="admin"','primary','shield'):''}${btn(t('logout'),'logout','','secondary','logout')}<div class="notice">${t('localNote')}</div></div>`}
function challenges(){
  const level=[[25000,'Legend'],[10000,'Champion'],[5000,'Elite'],[2000,'Warrior'],[500,'Athlete'],[0,'Rookie']].find(x=>state.me.xp>=x[0])[1];
  return `<div class="stack"><div class="hero">${art()}<span class="eyebrow">MUSCLIVO CHALLENGES</span><h1>${t('challenges')}</h1><div class="row"><div class="stat green">${state.me.xp} XP</div>${badge(level,'gold')}</div></div><div class="row space"><h2>${t('challenges')}</h2>${['coach','gym'].includes(state.me.role)&&state.me.verified?btn(t('create'),'createChallenge','','primary','plus'):''}</div><div class="grid">${state.challenges.map(c=>{const days=c.members[state.me.id];return `<div class="card stack"><div class="row space"><span class="gold">${ic('trophy')}</span>${badge(c.days+' '+t('days'))}</div><h2>${h(c.title)}</h2><small>${Object.keys(c.members).length} ${t('members')}</small>${days?`<progress value="${days.length}" max="${c.days}"></progress><small>${days.length} / ${c.days}</small>${days.length===c.days?badge(t('done')):btn(t('dailyCheck'),'checkin',`data-id="${c.id}"`,'primary')}`:btn(t('join'),'joinChallenge',`data-id="${c.id}"`,'primary')}</div>`}).join('')||empty()}</div></div>`}
function admin(){const a=state.admin;if(!a)return empty();const active=a.profiles.filter(p=>p.lastActive>Date.now()-30*86400000).length;return `<div class="stack"><div class="row space"><h1>ADMIN <span class="green">LIVE</span></h1>${badge('LOCAL')}</div><div class="notice">${t('adminNotice')}</div><div class="grid grid3">${stat(a.profiles.length,'users')}${stat(active,'active30')}${stat(a.reports.filter(x=>x.state==='pending').length,'reports')}</div><div class="card stack"><h3>${t('freeGoal')}</h3><div class="stat green">${active} / 10,000</div><progress value="${active}" max="10000"></progress></div><div class="card admin-list"><h2>${t('users')}</h2>${a.profiles.map(p=>`<div class="row rule"><div class="grow"><b>${h(p.name)}</b><br><small>${t(p.role)} ${p.verified?'✓':''}</small></div>${p.role!=='admin'?btn(t(p.suspended?'restore':'suspend'),'admin',`data-id="${p.id}" data-op="suspend"`,p.suspended?'secondary':'danger'):''}</div>`).join('')}</div><div class="card admin-list"><h2>${t('verifyRequests')}</h2>${a.verifications.map(v=>`<div class="row rule"><div class="grow"><b>${h(get(v.owner).name)}</b><p>${h(v.text)}</p><small>${h(v.state)}</small></div>${v.state==='pending'?btn(t('accept'),'admin',`data-id="${v.id}" data-op="verify" data-accept="true"`,'primary')+btn(t('decline'),'admin',`data-id="${v.id}" data-op="verify" data-accept="false"`):''}</div>`).join('')||empty()}</div><div class="card admin-list"><h2>${t('reports')}</h2>${a.reports.map(r=>`<div class="rule row"><div class="grow"><b>${h(r.targetType)}</b><p>${h(r.reason)}</p><small>${h(r.state)}</small></div>${r.state==='pending'?btn(t('resolve'),'admin',`data-id="${r.id}" data-op="resolve"`,'primary'):''}</div>`).join('')||empty()}</div><div class="card admin-list"><h2>${t('audit')}</h2>${a.audit.map(x=>`<div class="rule"><b>${h(x.operation)}</b> · <small>${displayDate(x.at)}</small></div>`).join('')||empty()}</div></div>`}
function modal(title,content,payload={}){modalPayload=payload;const el=$('#modal');el.innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-label="${h(title)}"><div class="row space"><h2>${h(title)}</h2><button class="icon-button" data-action="close" aria-label="${t('close')}">${ic('close')}</button></div>${content}</section>`;el.hidden=false;el.querySelector('input,textarea,button')?.focus()}
function closeModal(){$('#modal').hidden=true;modalPayload=null}
const field=(name,label,value='',type='text',required=false)=>`<label>${t(label)}<input name="${name}" type="${type}" value="${h(value)}" ${required?'required':''}></label>`;
const form=(type,inner,label='save')=>`<form class="form" data-form="${type}">${inner}<button type="submit" class="primary">${t(label)}</button></form>`;
const imageField=()=>`<label>${t('image')}<input type="file" name="image" accept="image/png,image/jpeg,image/webp"></label>`;
async function imageData(file){if(!file?.size)return '';if(file.size>12*1024*1024)throw new Error(t('imageLarge'));const src=URL.createObjectURL(file);try{const im=new Image();im.src=src;await im.decode();const canvas=document.createElement('canvas'),ratio=Math.min(1,900/Math.max(im.width,im.height));canvas.width=Math.round(im.width*ratio);canvas.height=Math.round(im.height*ratio);canvas.getContext('2d').drawImage(im,0,0,canvas.width,canvas.height);let data=canvas.toDataURL('image/jpeg',.72);if(data.length>=400000)data=canvas.toDataURL('image/jpeg',.4);if(data.length>=400000)throw new Error(t('imageLarge'));return data}finally{URL.revokeObjectURL(src)}}
async function act(type,b={}){if(busy)return;busy=true;try{state=await api('action',{type,...b});render();return true}catch(e){toast(e.message||t('error'));return false}finally{busy=false}}
async function sign(b){if(busy)return;busy=true;try{const result=await api('auth',b);authEmail=b.email||'';if(result.verificationRequired){authMode='verify';render();toast(t('codeSent'));return}if(result.ok&&!result.me){authMode=b.mode==='forgot'?'reset':b.mode==='resend'?'verify':'login';render();toast(t(b.mode==='forgot'||b.mode==='resend'?'codeSent':'success'));return}resetWorkspace();state=result;lang=b.lang||state.me.lang||lang;localStorage.setItem('ml-language',lang);page=state.me.role==='admin'?'admin':'home';render()}catch(e){toast(e.message)}finally{busy=false}}
document.addEventListener('click',async e=>{
  const el=e.target.closest('[data-action]');if(!el)return;const {action,id,tab,accept,op}=el.dataset;
  switch(action){
    case 'nav':page=id;render();window.scrollTo(0,0);break;
    case 'sampleToggle':if(!config.production&&canOpen(page,workspaceRole(state))){toggleSample(state,page,id);render()}break;
    case 'identitySwitch':if(state.identity&&!config.production)await act('identity',{operation:'switch',context:id});break;
    case 'identityResponse':if(state.identity&&!config.production)await act('identity',{operation:'respond',id,accept:el.dataset.accept==='true'});break;
    case 'identityRevoke':if(state.identity&&!config.production&&confirm(t('identityRevokeConfirm')))await act('identity',{operation:'revoke',id});break;
    case 'identityResolve':if(state.identity&&!config.production)await act('identity',{operation:'resolveReport',id});break;
    case 'coachLang':if(!config.production&&page==='coaches'){toggleCoachLanguage(state,id,lang);render()}break;
    case 'jump':page=id;if(tab)liveTab=tab;render();window.scrollTo(0,0);break;
    case 'sessionsNav':page='live';liveTab='sessions';render();break;
    case 'liveNav':page='live';liveTab='match';render();break;
    case 'authMode':authEmail=$('input[name=email]')?.value||authEmail;authMode=id;render();break;
    case 'resend':await sign({mode:'resend',email:$('input[name=email]')?.value||authEmail,lang});break;
    case 'demo':await sign({mode:'demo',role:id,lang});break;
    case 'logout':await api('logout',{});state=null;page='home';chatId=null;render();break;
    case 'feed':feed=id;render();break;
    case 'liveTab':liveTab=id;render();break;
    case 'setReady':await act('status',{status:'ready'});break;
    case 'filter':roleFilter=id;render();break;
    case 'onlineFilter':onlineOnly=!onlineOnly;render();break;
    case 'openChat':chatId=id;render();break;
    case 'newPost':modal(t('post'),form('post',`<label>${t('textPost')}<textarea name="text" maxlength="1500" placeholder="${t('shareThought')}"></textarea></label><label>${t('role')}<select name="kind">${[['text','textPost'],['workout','workout'],['record','record'],['checkin','checkin']].map(([v,k])=>`<option value="${v}">${t(k)}</option>`).join('')}</select></label>${imageField()}`,'post'));break;
    case 'newStory':modal(t('yourStory'),form('story',`<textarea name="text" maxlength="280" placeholder="${t('shareThought')}"></textarea>${imageField()}`,'post'));break;
    case 'viewStory':{const s=state.stories.find(x=>x.id===id);if(s)modal(get(s.owner).name,`<div class="stack"><p class="post-text">${h(s.text)}</p>${s.image?`<img class="story-image" src="${h(s.image)}" alt="${t('image')}">`:''}<small>${displayDate(s.at)}</small></div>`);break}
    case 'comments':{const p=state.posts.find(x=>x.id===id);modal(t('comments'),`<div class="stack">${p.comments.map(c=>`<div class="rule row">${avatar(get(c.owner))}<div><b>${h(get(c.owner).name)}</b><p>${h(c.text)}</p></div></div>`).join('')}</div>${form('comment',`<input name="text" required maxlength="500" placeholder="${t('comment')}">`,'send')}`,{id});break}
    case 'like':case 'save':case 'joinSession':case 'joinChallenge':case 'checkin':await act(action,{id});break;
    case 'deletePost':if(confirm(t('confirmDelete')))await act(action,{id});break;
    case 'share':{const p=state.posts.find(x=>x.id===id);try{await navigator.clipboard.writeText(p.text+' — MUSCLIVO LIVE');toast(t('success'))}catch{toast(p.text)}break}
    case 'follow':case 'block':await act(action,{target:id});break;
    case 'request':if(await act('request',{target:id,sport:state.me.sport}))toast(t('success'));break;
    case 'respond':case 'respondFollow':await act(action,{id,accept:accept==='true'});break;
    case 'readNotifications':await act(action);break;
    case 'admin':await act('admin',{operation:op,id,accept:accept==='true'});break;
    case 'reportPost':case 'reportProfile':modal(t('report'),form('report',`<label>${t('reason')}<textarea name="reason" maxlength="400" required></textarea></label>`,'send'),{id,targetType:action==='reportPost'?'post':'profile',target:id});break;
    case 'editProfile':{const p=state.me;modal(t('edit'),form('profile',field('name','name',p.name,'text',true)+field('city','city',p.city)+field('sport','sport',p.sport)+field('goal','goal',p.goal)+field('level','level',p.level)+(!config.production&&p.role==='coach'?`<div class="stack"><b>${t('spokenLanguages')}</b>${langs.map(l=>`<label class="check-row"><input type="checkbox" name="spokenLanguages" value="${l}" ${(p.spokenLanguages||[p.lang]).includes(l)?'checked':''}>${t('lang_'+l)}</label>`).join('')}</div>`:'')+`<label>${t('bio')}<textarea name="bio" maxlength="280">${h(p.bio)}</textarea></label>`));break}
    case 'newChat':modal(t('newChat'),form('conversation',field('name','groupName')+`<div class="stack"><small>${t('choosePeople')}</small>${state.profiles.filter(p=>p.id!==state.me.id).map(p=>`<label class="check-row"><input type="checkbox" name="members" value="${p.id}">${h(p.name)}</label>`).join('')}</div>`,'create'));break;
    case 'directChat':if(await act('conversation',{members:[id]})){chatId=state.conversations.find(c=>c.members.length===2&&c.members.includes(id))?.id;page='chat';render()}break;
    case 'invite':modal(t('invite'),form('invite',field('title','sport','','text',true)+field('at','date','','datetime-local',true),'send'),{id});break;
    case 'newSession':modal(t('newSession'),form('session',field('title','sessionTitle','','text',true)+field('sport','sport',state.me.sport,'text',true)+field('at','date','','datetime-local',true),'create'));break;
    case 'verification':modal(t('verification'),form('verification',`<label>${t('verificationText')}<textarea name="text" required maxlength="800"></textarea></label>`,'send'));break;
    case 'createChallenge':modal(t('challenges'),form('createChallenge',field('title','name','','text',true)+`<label>${t('days')}<select name="days"><option value="7">7</option><option value="14">14</option><option value="30">30</option></select></label>`,'create'));break;
    case 'account':modal(t(id),form('account',`${id==='deleteAccount'?'<p class="red">'+t('deleteWarning')+'</p>':''}${field('password','password','','password',true)}${id==='deleteAccount'?'<label class="check-row"><input type="checkbox" name="confirm" required>'+t('confirmDeleteAccount')+'</label>':''}`,id),{operation:{deleteAccount:'delete',dataExport:'export',logoutAll:'logoutAll'}[id]});break;
    case 'close':closeModal();break;
  }
});
document.addEventListener('change',async e=>{
  if(e.target.id==='lang-select'){lang=e.target.value;localStorage.setItem('ml-language',lang);if(state)await act('settings',{lang});else render()}
  if(e.target.id==='presence')await act('status',{status:e.target.value});
});
document.addEventListener('submit',async e=>{
  const f=e.target.closest('[data-form]');if(!f)return;e.preventDefault();const type=f.dataset.form,fd=new FormData(f),data=Object.fromEntries(fd);
  if(type==='auth'){await sign({...data,mode:authMode,lang,acceptPolicies:fd.has('acceptPolicies'),adult:fd.has('adult')});return}
  if(type==='search'){query=data.query||'';render();return}
  if(type==='identity'){if(!state.identity||config.production)return;await act('identity',{...data,clubId:data.clubId||null});return}
  try{
    const b={...data,...modalPayload};
    if(type==='post'||type==='story')b.image=await imageData(fd.get('image'));
    if(type==='conversation')b.members=fd.getAll('members');
    if(type==='profile'&&!config.production&&state.me.role==='coach')b.spokenLanguages=fd.getAll('spokenLanguages');
    if(type==='session')b.at=new Date(data.at).getTime();
    if(type==='settings'){for(const k of ['presence','match','notifications'])b[k]=fd.has(k);lang=b.lang;localStorage.setItem('ml-language',lang)}
    if(type==='message')b.id=f.dataset.id;
    if(type==='account'){const result=await api('account',{...b,confirm:fd.has('confirm')});if(b.operation==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='musclivo-live-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}else {state=null;authMode='login';render()}closeModal();toast(t('success'));return}
    let ok;if(type==='invite')ok=await act('message',{id:b.id,text:t('inviteText')+' '+data.title+' · '+displayDate(new Date(data.at).getTime())});else ok=await act(type,b);
    if(ok){closeModal();if(type==='conversation'){page='chat';chatId=state.conversations.at(-1)?.id;render()}toast(t('success'))}
  }catch(err){toast(err.message||t('error'))}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
async function init(){try{config=await api('config')}catch{}try{state=await api('state');lang=state.me.lang||lang;page=state.me.role==='admin'?'admin':'home'}catch{}render()}
init();
setInterval(async()=>{if(!state||busy||!$('#modal').hidden||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;try{state=await api('state');render()}catch(e){if(e.status===401){state=null;render()}}},15000);

